(function(){
var ST=window.ST,BA=ST.BA,esc=ST.esc,$=ST.$,staff=ST.staff,FV=window.FV;if(!staff||!$('app'))return;
var isC=staff.role==='circle',cir=FV.dir().filter(function(m){return m.role==='circle'}),cid=isC?staff.id:(BA.ls('ba3_cirsel')||(cir[0]||{}).id),tab=BA.qs.get('t')||'ov';
function me(){return FV.get(cid)}
function team(){return FV.dir().filter(function(m){return m.role==='dsm'&&m.manager===cid})}
function render(){var m=me();if(!m){$('app').innerHTML=ST.head('Circle','No Circle Manager account exists. Onboard one in Admin, Staff.');return}FV.sweep();
 var ids=team().map(function(x){return x.id}),br=FV.breaches().filter(function(b){return ids.indexOf(b.dsm)>-1&&!b.soft}),sel=isC?'':'<select id="csel" class="cs" style="color:var(--ink)" aria-label="Circle Manager">'+cir.map(function(x){return '<option value="'+x.id+'"'+(x.id===cid?' selected':'')+'>'+esc(x.name)+' · '+esc(x.state)+'</option>'}).join('')+'</select>',
 q=FV.orders().filter(function(o){return ids.indexOf(o.dsm)>-1&&o.st==='sent'&&(!o.qa||o.qa.st==='pending')});
 $('app').innerHTML=ST.head('Circle · '+esc(m.name),esc(m.state)+' · '+team().length+' District Sales Managers',sel)+'<div class="kpis">'+ST.kpi('Slippages in your circle',br.length,'Past the promised time')+ST.kpi('Reports to review',q.length,'Emailed, quality check pending')+ST.kpi('District Sales Managers',team().length,'Reporting to you')+ST.kpi('Field engineers',FV.dir().filter(function(e){return e.role==='field'&&ids.indexOf(e.manager)>-1}).length,'Across your districts')+'</div>'+
 ST.tabsHtml([['ov','Escalations ('+br.length+')'],['tm','District Sales Managers'],['qa','Report quality ('+q.length+')'],['pf','DSM performance'],['ix','Customer interactions'],['ex','Engineer interactions'],['cl','With Leadership'],['jr','Customer journeys'],['al','Alerts']],tab)+'<div id="tb"></div>';
 $('tabs').onclick=function(e){var b=e.target.closest('button');if(b){tab=b.dataset.t;render()}};if($('csel'))$('csel').onchange=function(){cid=this.value;BA.ls('ba3_cirsel',cid);render()};
 ({ov:ov,tm:tm,qa:qa,al:al,pf:pf,ix:ix,ex:ex,cl:cl,jr:jr})[tab](ids,br,q)}
function ov(ids,br){$('tb').innerHTML=ST.panel('Escalated to you ('+br.length+')','<p style="color:var(--mute);margin:0 0 10px;font-size:13px">These are 6 hours or more late, or a report past its 72 hour promise. Call the District Sales Manager and agree a recovery plan. Anything still open after 24 hours goes to Leadership automatically.</p>'+ST.table(['Property','Owner','District Sales Manager','What slipped','Late by','Goes to leadership in',''],br.map(function(b){var d=FV.get(b.dsm),toL=24*36e5-b.over;return '<tr><td><b>'+esc(b.prop)+'</b><br><small style="color:var(--mute)">'+b.pid+'</small></td><td>'+esc(b.owner)+'</td><td>'+(d?esc(d.name)+'<br><small>'+FV.tel(d.phone)+'</small>':'—')+'</td><td>'+esc(b.text)+'</td><td><b style="color:#A50E0E">'+FV.left(b.over)+'</b></td><td>'+(toL>0?FV.left(toL):'<b style="color:#A50E0E">Already with leadership</b>')+'</td><td><button class="btn out sm" data-n="'+b.pid+'|'+(b.dsm||'')+'">Nudge DSM</button></td></tr>'}))+(br.length?'':'<p style="color:var(--mute);margin:10px 0 0">Nothing is late in your circle.</p>'));
 $('tb').onclick=function(e){var t=e.target.closest('[data-n]');if(!t)return;var q=t.dataset.n.split('|'),p=FV.property(q[0]);FV.notify(null,{type:'nudge',prop:q[0],to:['mgr:'+q[1]],sev:'red',text:'Circle Manager '+me().name+' asks for an update on '+p.short+', '+p.loc+' today.'});ST.log('Nudged DSM about '+q[0]);BA.toast('District Sales Manager reminded')}}
function tm(ids,br){$('tb').innerHTML=ST.panel('Your District Sales Managers',ST.table(['District Sales Manager','Districts','Field engineers','To assign','Report orders open','Slippages'],team().map(function(d){var es=FV.team(d.id),dq=Object.keys(FV.dq()).filter(function(k){return FV.dq()[k].dsm===d.id&&FV.dq()[k].st==='new'}).length,oo=FV.orders().filter(function(o){return o.dsm===d.id&&o.st!=='sent'}).length,n=br.filter(function(b){return b.dsm===d.id}).length;return '<tr><td><b>'+esc(d.name)+'</b><br><small style="color:var(--mute)">'+FV.tel(d.phone)+'</small></td><td>'+esc((d.districts||[]).join(', '))+'</td><td>'+es.map(function(e){return esc(e.name)}).join(', ')+'</td><td>'+dq+'</td><td>'+oo+'</td><td>'+(n?'<b style="color:#A50E0E">'+n+'</b>':0)+'</td></tr>'})))+FV.slaPanel({state:me().state})}
function qa(ids,br,q){$('tb').innerHTML=ST.panel('Quality check on emailed reports ('+q.length+')','<p style="color:var(--mute);margin:0 0 10px;font-size:13px">Read a sample of what customers received. Mark it fine, or raise a concern. Concerns go to Leadership with your note.</p>'+ST.table(['Report','Property','District Sales Manager','Sent','Result',''],q.map(function(o){var p=FV.property(o.pid)||{short:o.pid,loc:''},d=FV.get(o.dsm);return '<tr><td><b>'+o.id+'</b></td><td>'+esc(p.short)+'<br><small style="color:var(--mute)">'+esc(p.loc)+'</small></td><td>'+(d?esc(d.name):'')+'</td><td>'+FV.when(o.sentAt)+(o.sentAt>o.due?' '+ST.chip('Late','r'):'')+'</td><td>'+FV.RPT.filter(function(s){return o.sec[s[0]]&&o.sec[s[0]].done}).length+' of '+FV.RPT.length+' sections</td><td style="white-space:nowrap"><button class="btn sm" data-ok="'+o.id+'">Looks good</button> <button class="btn out sm" data-fl="'+o.id+'">Raise concern</button></td></tr>'}))+(q.length?'':'<p style="color:var(--mute);margin:10px 0 0">Every emailed report has been checked.</p>'));
 $('tb').onclick=function(e){var t=e.target.closest('button');if(!t)return;var O=FV.orders();
  if(t.dataset.ok){var o=O.filter(function(x){return x.id===t.dataset.ok})[0];o.qa={st:'ok',by:me().name,at:Date.now()};o.hist.push({at:Date.now(),who:me().name,what:'Quality check passed'});FV.saveOrders(O);ST.log('Quality check passed on '+o.id);BA.toast('Marked as checked');render()}
  if(t.dataset.fl){var id=t.dataset.fl;BA.box('<h3>Raise a concern on '+id+'</h3><div class="form" style="max-width:none"><label>What is wrong? (required)<textarea id="fw"></textarea></label><div id="fe" class="ok" style="background:#FFE9EE;color:#9B1C47" hidden>Describe the concern in a sentence or two.</div><button class="btn" id="fg">Send to leadership</button></div>');$('fg').onclick=function(){var w=$('fw').value.trim();if(w.length<10){$('fe').hidden=false;return}var O2=FV.orders(),o=O2.filter(function(x){return x.id===id})[0],p=FV.property(o.pid);o.qa={st:'flag',by:me().name,at:Date.now(),why:w};o.hist.push({at:Date.now(),who:me().name,what:'Concern raised: '+w});FV.saveOrders(O2);var ex=BA.jget('ba3_rptx',[]);ex.push({order:id,prop:p.short+', '+p.loc,by:me().name,why:w,at:Date.now(),state:me().state});BA.jset('ba3_rptx',ex);FV.notify(null,{type:'rptflag',prop:o.pid,to:['leadership','admin','mgr:'+o.dsm],sev:'red',text:'Circle Manager '+me().name+' raised a concern on report '+id+' ('+p.short+'): '+w});ST.log('Raised concern on '+id);BA.closeBox();BA.toast('Sent to leadership');render()}}}}
function mP(){var m=me();return {id:m.id,name:m.name,role:'circle'}}
function pf(){window.DASH.circleView($('tb'),cid)}
function ix(){TRK.tracker($('tb'),TRK.cfgCust(mP(),'circle'))}
function ex(){TRK.tracker($('tb'),TRK.cfgEng(mP()))}
function cl(){TRK.tracker($('tb'),TRK.cfgCir(mP()))}
function jr(){TRK.journey($('tb'),TRK.cfgJr(mP()))}
function al(){$('tb').innerHTML=ST.panel('Alerts for you',ST.table(['When','Alert'],FV.notifs('mgr:'+cid).slice(0,40).map(function(n){return '<tr><td style="white-space:nowrap">'+ST.ago(n.at)+'</td><td>'+(n.sev==='red'?'<span style="color:#A50E0E">●</span> ':n.sev==='amber'?'<span style="color:#8A5A00">●</span> ':'')+esc(n.text)+'</td></tr>'})))}
render();
})();
